 22	/*
 23	 * Two kinds of test. Every record is built by the test; none is a
 24	 * measurement, and no sensor is used.
 25	 * - FILE: real syscalls against a fresh directory from mkdtemp, removed at
 26	 *   the end. These check what actually reaches the file.
 27	 * - SIMULATED: a fake syscall table scripts failures and records every
 28	 *   call, so each error path runs deterministically.
 29	 */
 30	
 31	#define NS_PER_SEC UINT64_C(1000000000)
 32	#define PATH_CAP 512
 33	#define FAKE_DIR_FD 50
 34	#define FAKE_FILE_FD 51
 35	#define FAKE_MAX_CLOSES 4
 36	#define FAKE_WRITTEN_CAP (4 * STORAGE_LOG_BATCH_BYTES)
 37	
 38	/* ---------- shared helpers ---------- */
 39	
 40	/* test_record: a valid light record with sequence seq; value tracks seq. */
 41	static storage_record test_record(uint64_t seq, int simulated)
 42	{
 43	    storage_record r;
 44	
 45	    memset(&r, 0, sizeof r);
 46	    r.record_type = STORAGE_RECORD_TYPE_LIGHT;
 47	    r.flags = STORAGE_FLAG_VALID | STORAGE_FLAG_CLOCK_UNTRUSTED;
 48	    if (simulated)
 49	        r.flags |= STORAGE_FLAG_SIMULATED;
 50	    r.sequence = seq;
 51	    r.wall_clock_ns = seq * NS_PER_SEC;
 52	    r.monotonic_ns = seq * NS_PER_SEC + 7;
 53	    r.sensor_value = (uint32_t)(seq * 1000u);
 54	    r.source_sequence = (uint32_t)seq;
 55	    return r;
 56	}
 57	
 58	/* check_bytes_hold: bytes hold n records with sequences first, first+1... */
 59	static void check_bytes_hold(const uint8_t *bytes, size_t len_bytes,
 60	                             uint64_t first, size_t n, int simulated)
 61	{
 62	    size_t i;
 63	
 64	    assert(len_bytes == n * STORAGE_RECORD_SIZE_BYTES);
 65	    for (i = 0; i < n; i++) {
 66	        storage_record out;
 67	        storage_record want = test_record(first + i, simulated);
 68	
 69	        assert(storage_record_decode(bytes + i * STORAGE_RECORD_SIZE_BYTES,
 70	                                     &out) == STORAGE_RECORD_OK);
 71	        assert(out.sequence == want.sequence);
 72	        assert(out.flags == want.flags);
 73	        assert(out.sensor_value == want.sensor_value);
 74	        assert(out.monotonic_ns == want.monotonic_ns);
 75	    }
 76	}
