 99	/* ---------- FILE tests: real syscalls in a temporary directory ---------- */
100	
101	static char temp_dir[PATH_CAP];
102	
103	/* make_temp_dir: create a fresh, empty directory for one test. */
104	static void make_temp_dir(void)
105	{
106	    const char *base = getenv("TMPDIR");
107	    int n;
108	
109	    if (base == NULL || base[0] == '\0')
110	        base = "/tmp";
111	    n = snprintf(temp_dir, sizeof temp_dir, "%s/storage-log-test.XXXXXX",
112	                 base);
113	    assert(n > 0 && (size_t)n < sizeof temp_dir);
114	    assert(mkdtemp(temp_dir) != NULL);
115	}
116	
117	/* file_path: write temp_dir/name into buf. */
118	static void file_path(char *buf, size_t size, const char *name)
119	{
120	    int n = snprintf(buf, size, "%s/%s", temp_dir, name);
121	
122	    assert(n > 0 && (size_t)n < size);
123	}
124	
125	/* remove_temp_file: delete temp_dir/name. */
126	static void remove_temp_file(const char *name)
127	{
128	    char path[PATH_CAP];
129	
130	    file_path(path, sizeof path, name);
131	    assert(unlink(path) == 0);
132	}
133	
134	/* remove_temp_dir: delete the (now empty) temporary directory. */
135	static void remove_temp_dir(void)
136	{
137	    assert(rmdir(temp_dir) == 0);
138	}
