140	/* read_file: read all of temp_dir/name into buf; return its length. */
141	static size_t read_file(const char *name, uint8_t *buf, size_t cap)
142	{
143	    char path[PATH_CAP];
144	    FILE *f;
145	    size_t n;
146	
147	    file_path(path, sizeof path, name);
148	    f = fopen(path, "rb");
149	    assert(f != NULL);
150	    n = fread(buf, 1, cap, f);
151	    assert(!ferror(f));
152	    assert(fgetc(f) == EOF);  /* the whole file fit in buf */
153	    assert(fclose(f) == 0);
154	    return n;
155	}
156	
157	/* write_file: replace temp_dir/name with len_bytes of buf. */
158	static void write_file(const char *name, const uint8_t *buf, size_t len)
159	{
160	    char path[PATH_CAP];
161	    FILE *f;
162	
163	    file_path(path, sizeof path, name);
164	    f = fopen(path, "wb");
165	    assert(f != NULL);
166	    assert(fwrite(buf, 1, len, f) == len);
167	    assert(fclose(f) == 0);
168	}
169	
170	/* file_size: size of temp_dir/name in bytes. */
171	static off_t file_size(const char *name)
172	{
173	    char path[PATH_CAP];
174	    struct stat st;
175	
176	    file_path(path, sizeof path, name);
177	    assert(stat(path, &st) == 0);
178	    return st.st_size;
179	}
