181	/* FILE: appends stay in memory until flush, then reach the file in order. */
182	static void test_file_flush_writes_in_order(void)
183	{
184	    static storage_log_writer w;
185	    uint8_t buf[FAKE_WRITTEN_CAP];
186	    storage_record r;
187	    uint64_t seq;
188	    int fd;
189	
190	    make_temp_dir();
191	    expect_ok(storage_log_open(&w, temp_dir, "a.log", 10, 0));
192	    assert(w.fd >= 0);
193	    assert(w.file_size_bytes == 0);
194	    assert(file_size("a.log") == 0);
195	
196	    for (seq = 10; seq < 13; seq++) {
197	        r = test_record(seq, 0);
198	        expect_ok(storage_log_append(&w, &r, seq));
199	    }
200	    assert(w.buffered_records == 3);
201	    assert(file_size("a.log") == 0);
202	
203	    expect_ok(storage_log_flush(&w));
204	    assert(w.buffered_records == 0);
205	    assert(w.file_size_bytes == 3 * STORAGE_RECORD_SIZE_BYTES);
206	    check_bytes_hold(buf, read_file("a.log", buf, sizeof buf), 10, 3, 0);
207	
208	    fd = w.fd;
209	    expect_ok(storage_log_close(&w));
210	    assert(w.fd == -1);
211	    assert(fd_is_closed(fd));
212	
213	    remove_temp_file("a.log");
214	    remove_temp_dir();
215	}
