245	/* FILE: flush_if_due waits 60 s from the oldest buffered record. */
246	static void test_file_flush_if_due(void)
247	{
248	    static storage_log_writer w;
249	    const uint64_t t0 = 5 * NS_PER_SEC;
250	    storage_record r;
251	
252	    make_temp_dir();
253	    expect_ok(storage_log_open(&w, temp_dir, "c.log", 1, 0));
254	
255	    /* Nothing buffered: never due. */
256	    expect_ok(storage_log_flush_if_due(&w, UINT64_MAX));
257	
258	    r = test_record(1, 0);
259	    expect_ok(storage_log_append(&w, &r, t0));
260	    r = test_record(2, 0);
261	    expect_ok(storage_log_append(&w, &r, t0 + 30 * NS_PER_SEC));
262	    assert(w.oldest_buffered_ns == t0);
263	
264	    expect_ok(storage_log_flush_if_due(&w, t0 + 60 * NS_PER_SEC - 1));
265	    assert(file_size("c.log") == 0);
266	    /* A clock reading before the oldest record is never due. */
267	    expect_ok(storage_log_flush_if_due(&w, t0 - 1));
268	    assert(file_size("c.log") == 0);
269	
270	    expect_ok(storage_log_flush_if_due(&w, t0 + 60 * NS_PER_SEC));
271	    assert(w.buffered_records == 0);
272	    assert(file_size("c.log") == 2 * STORAGE_RECORD_SIZE_BYTES);
273	
274	    /* The deadline restarts from the next record after a flush. */
275	    r = test_record(3, 0);
276	    expect_ok(storage_log_append(&w, &r, t0 + 100 * NS_PER_SEC));
277	    expect_ok(storage_log_flush_if_due(&w, t0 + 159 * NS_PER_SEC));
278	    assert(w.buffered_records == 1);
279	    expect_ok(storage_log_flush_if_due(&w, t0 + 160 * NS_PER_SEC));
280	    assert(w.buffered_records == 0);
281	
282	    expect_ok(storage_log_close(&w));
283	    remove_temp_file("c.log");
284	    remove_temp_dir();
285	}
