365	/* FILE: bad records are rejected before anything is buffered. */
366	static void test_file_rejects_bad_records(void)
367	{
368	    static storage_log_writer w;
369	    storage_record r;
370	
371	    make_temp_dir();
372	    expect_ok(storage_log_open(&w, temp_dir, "h.log", 7, 0));
373	
374	    r = test_record(8, 0);  /* skips 7 */
375	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_SEQUENCE,
376	           STORAGE_LOG_STAGE_NONE, 0);
377	    r = test_record(6, 0);  /* goes back */
378	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_SEQUENCE,
379	           STORAGE_LOG_STAGE_NONE, 0);
380	
381	    r = test_record(7, 1);  /* SIMULATED record into a live file */
382	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_SIMULATED_MISMATCH,
383	           STORAGE_LOG_STAGE_NONE, 0);
384	
385	    r = test_record(7, 0);
386	    r.record_type = 0;
387	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_BAD_RECORD,
388	           STORAGE_LOG_STAGE_NONE, 0);
389	    r.record_type = STORAGE_RECORD_TYPE_START + 1;
390	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_BAD_RECORD,
391	           STORAGE_LOG_STAGE_NONE, 0);
392	    r = test_record(7, 0);
393	    r.flags |= UINT16_C(0x0010);  /* reserved bit 4 */
394	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_BAD_RECORD,
395	           STORAGE_LOG_STAGE_NONE, 0);
396	
397	    assert(w.buffered_records == 0);
398	    assert(w.next_sequence == 7);
399	
400	    /* The rejected attempts did not consume the sequence number. */
401	    r = test_record(7, 0);
402	    r.record_type = STORAGE_RECORD_TYPE_START;
403	    expect_ok(storage_log_append(&w, &r, 0));
404	    assert(w.next_sequence == 8);
405	    expect_ok(storage_log_close(&w));
406	    assert(file_size("h.log") == STORAGE_RECORD_SIZE_BYTES);
407	
408	    /* A simulated file refuses a record without the SIMULATED flag. */
409	    expect_ok(storage_log_open(&w, temp_dir, "i.log", 0, 1));
410	    r = test_record(0, 0);
411	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_SIMULATED_MISMATCH,
412	           STORAGE_LOG_STAGE_NONE, 0);
413	    expect_ok(storage_log_close(&w));
414	    assert(file_size("i.log") == 0);
415	
416	    remove_temp_file("h.log");
417	    remove_temp_file("i.log");
418	    remove_temp_dir();
419	}
