461	/* ---------- SIMULATED tests: scripted syscall failures ---------- */
462	
463	/* Fake syscall state: scripted results, then a record of each call. */
464	typedef struct {
465	    int open_dir_errno;     /* nonzero: open_dir fails with this errno */
466	    int open_file_errno;    /* nonzero: open_append_at fails */
467	    int fstat_errno;        /* nonzero: fstat fails */
468	    off_t existing_bytes;   /* size fstat reports */
469	    int fsync_errno;        /* nonzero: fsync (of the directory) fails */
470	    int write_eintr_count;  /* first n writes fail with EINTR */
471	    size_t write_chunk;     /* nonzero: each write accepts at most this */
472	    int write_errno;        /* nonzero: writes fail after the EINTRs */
473	    size_t write_errno_after;  /* ...once this many bytes were accepted */
474	    int fdatasync_errno;    /* nonzero: fdatasync fails */
475	    int close_fail_fd;      /* close of this fd fails with close_errno */
476	    int close_errno;
477	
478	    unsigned open_dir_calls;
479	    unsigned open_file_calls;
480	    unsigned fstat_calls;
481	    unsigned write_calls;
482	    unsigned fdatasync_calls;
483	    unsigned fsync_calls;
484	    unsigned close_calls;
485	    int open_file_dir_fd;
486	    int fsync_fd;
487	    int fdatasync_fd;
488	    int closed_fds[FAKE_MAX_CLOSES];
489	    uint8_t written[FAKE_WRITTEN_CAP];
490	    size_t written_len;
491	} fake_state;
492	
493	static fake_state fake;
494	
495	/* fake_reset: clear all scripted results and call records. */
496	static void fake_reset(void)
497	{
498	    memset(&fake, 0, sizeof fake);
499	    fake.close_fail_fd = -1;
500	}
501	
502	/* fake_open_dir: hand out FAKE_DIR_FD, or fail as scripted. */
503	static int fake_open_dir(const char *path)
504	{
505	    (void)path;
506	    fake.open_dir_calls++;
507	    if (fake.open_dir_errno != 0) {
508	        errno = fake.open_dir_errno;
509	        return -1;
510	    }
511	    return FAKE_DIR_FD;
512	}
513	
514	/* fake_open_append_at: hand out FAKE_FILE_FD, or fail as scripted. */
515	static int fake_open_append_at(int dir_fd, const char *name)
516	{
517	    (void)name;
518	    fake.open_file_calls++;
519	    fake.open_file_dir_fd = dir_fd;
520	    if (fake.open_file_errno != 0) {
521	        errno = fake.open_file_errno;
522	        return -1;
523	    }
524	    return FAKE_FILE_FD;
525	}
526	
527	/* fake_fstat: report existing_bytes, or fail as scripted. */
528	static int fake_fstat(int fd, struct stat *st)
529	{
530	    (void)fd;
531	    fake.fstat_calls++;
532	    if (fake.fstat_errno != 0) {
533	        errno = fake.fstat_errno;
534	        return -1;
535	    }
536	    memset(st, 0, sizeof *st);
537	    st->st_size = fake.existing_bytes;
538	    return 0;
539	}
540	
541	/* fake_write: EINTR, fail, or accept up to write_chunk bytes. */
542	static ssize_t fake_write(int fd, const void *buf, size_t len)
543	{
544	    assert(fd == FAKE_FILE_FD);
545	    fake.write_calls++;
546	    if (fake.write_eintr_count > 0) {
547	        fake.write_eintr_count--;
548	        errno = EINTR;
549	        return -1;
550	    }
551	    if (fake.write_errno != 0 &&
552	        fake.written_len >= fake.write_errno_after) {
553	        errno = fake.write_errno;
554	        return -1;
555	    }
556	    if (fake.write_chunk != 0 && len > fake.write_chunk)
557	        len = fake.write_chunk;
558	    assert(fake.written_len + len <= sizeof fake.written);
