463	   463	/* Fake syscall state: scripted results, then a record of each call. */
464	   464	typedef struct {
465	   465	    int open_dir_errno;     /* nonzero: open_dir fails with this errno */
466	   466	    int open_file_errno;    /* nonzero: open_append_at fails */
467	   467	    int fstat_errno;        /* nonzero: fstat fails */
468	   468	    off_t existing_bytes;   /* size fstat reports */
469	   469	    int fsync_errno;        /* nonzero: fsync (of the directory) fails */
470	   470	    int write_eintr_count;  /* first n writes fail with EINTR */
471	   471	    size_t write_chunk;     /* nonzero: each write accepts at most this */
472	   472	    int write_errno;        /* nonzero: writes fail after the EINTRs */
473	   473	    size_t write_errno_after;  /* ...once this many bytes were accepted */
474	   474	    int fdatasync_errno;    /* nonzero: fdatasync fails */
475	   475	    int close_fail_fd;      /* close of this fd fails with close_errno */
476	   476	    int close_errno;
477	   477	
478	   478	    unsigned open_dir_calls;
479	   479	    unsigned open_file_calls;
480	   480	    unsigned fstat_calls;
481	   481	    unsigned write_calls;
482	   482	    unsigned fdatasync_calls;
483	   483	    unsigned fsync_calls;
484	   484	    unsigned close_calls;
485	   485	    int open_file_dir_fd;
486	   486	    int fsync_fd;
487	   487	    int fdatasync_fd;
488	   488	    int closed_fds[FAKE_MAX_CLOSES];
489	   489	    uint8_t written[FAKE_WRITTEN_CAP];
490	   490	    size_t written_len;
491	   491	} fake_state;
