541	   541	/* fake_write: EINTR, fail, or accept up to write_chunk bytes. */
542	   542	static ssize_t fake_write(int fd, const void *buf, size_t len)
543	   543	{
544	   544	    assert(fd == FAKE_FILE_FD);
545	   545	    fake.write_calls++;
546	   546	    if (fake.write_eintr_count > 0) {
547	   547	        fake.write_eintr_count--;
548	   548	        errno = EINTR;
549	   549	        return -1;
550	   550	    }
551	   551	    if (fake.write_errno != 0 &&
552	   552	        fake.written_len >= fake.write_errno_after) {
553	   553	        errno = fake.write_errno;
554	   554	        return -1;
555	   555	    }
556	   556	    if (fake.write_chunk != 0 && len > fake.write_chunk)
557	   557	        len = fake.write_chunk;
558	   558	    assert(fake.written_len + len <= sizeof fake.written);
559	   559	    memcpy(fake.written + fake.written_len, buf, len);
560	   560	    fake.written_len += len;
561	   561	    return (ssize_t)len;
562	   562	}
