365	/* FILE: bad records are rejected before anything is buffered. */
366	static void test_file_rejects_bad_records(void)
367	{
368	    static storage_log_writer w;
369	    storage_record r;
370	
371	    make_temp_dir();
372	    expect_ok(storage_log_open(&w, temp_dir, "h.log", 7, 0));
373	
374	    r = test_record(8, 0);  /* skips 7 */
375	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_SEQUENCE,
376	           STORAGE_LOG_STAGE_NONE, 0);
377	    r = test_record(6, 0);  /* goes back */
378	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_SEQUENCE,
379	           STORAGE_LOG_STAGE_NONE, 0);
380	
381	    r = test_record(7, 1);  /* SIMULATED record into a live file */
382	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_SIMULATED_MISMATCH,
383	           STORAGE_LOG_STAGE_NONE, 0);
384	
385	    r = test_record(7, 0);
386	    r.record_type = 0;
387	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_BAD_RECORD,
388	           STORAGE_LOG_STAGE_NONE, 0);
389	    r.record_type = STORAGE_RECORD_TYPE_START + 1;
390	    expect(storage_log_append(&w, &r, 0), STORAGE_LOG_BAD_RECORD,
